import sqlite3
import sys
import json
from typing import Dict, List, Optional, Tuple, Union

def run_query(db_path: str, table: str, filters: Dict[str, Union[str, int, float, None]], order_by: Optional[Tuple[str, str]] = None, limit: Optional[int] = None) -> List[Dict[str, Union[str, int, float]]]:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()

    # Build WHERE clause
    where_conditions = []
    params = []
    for col, val in filters.items():
        if val is not None:
            where_conditions.append(f"{col} = ?")
            params.append(val)

    query = f"SELECT * FROM {table}"
    if where_conditions:
        query += " WHERE " + " AND ".join(where_conditions)

    # Build ORDER BY clause
    if order_by:
        col, direction = order_by
        query += f" ORDER BY {col} {direction}"

    # Add LIMIT clause
    if limit is not None:
        query += f" LIMIT {limit}"

    cursor.execute(query, params)
    columns = [desc[0] for desc in cursor.description]
    rows = cursor.fetchall()

    result = []
    for row in rows:
        row_dict = dict(zip(columns, row))
        result.append(row_dict)

    conn.close()
    return result

def parse_filters(args: List[str]) -> Dict[str, Union[str, int, float, None]]:
    filters = {}
    i = 0
    while i < len(args):
        if args[i].startswith('--order-by'):
            i += 1
            if i >= len(args):
                raise ValueError("Missing value for --order-by")
            order_by = args[i].split(':')
            if len(order_by) != 2 or order_by[0] not in columns:
                raise ValueError("Invalid --order-by format")
            return None, (order_by[0], order_by[1])
        elif args[i].startswith('--limit'):
            i += 1
            if i >= len(args):
                raise ValueError("Missing value for --limit")
            try:
                limit = int(args[i])
            except ValueError:
                raise ValueError("--limit must be an integer")
            return None, None, limit
        elif '=' in args[i]:
            col, val = args[i].split('=', 1)
            try:
                filters[col] = int(val)
            except ValueError:
                try:
                    filters[col] = float(val)
                except ValueError:
                    filters[col] = val
            i += 1
        else:
            filters[args[i]] = None
            i += 1
    return filters, None, None

def get_columns(db_path: str, table: str) -> List[str]:
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute(f"PRAGMA table_info({table})")
    columns = [desc[1] for desc in cursor.fetchall()]
    conn.close()
    return columns

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python dynamic_query.py <db_path> <table> [column=value ...] [--order-by column:ASC|DESC] [--limit N]", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]
    table = sys.argv[2]
    columns = get_columns(db_path, table)
    filters, order_by, limit = parse_filters(sys.argv[3:])

    result = run_query(db_path, table, filters, order_by, limit)

    for row in result:
        print(json.dumps(row))
